<?php
require_once __DIR__.'/../../../config/database.php';
require_once __DIR__.'/../../../includes/session.php';
require_once __DIR__.'/../../../includes/pds_paper.php';
checkLogin();$user_info=getUserInfo();header('Cache-Control: private, no-store');
if(!in_array($user_info['role']??'',['admin','guidance_advocate','super_admin'],true)){http_response_code(403);echo 'You do not have permission to view this record.';exit;}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
if(!$id||$id<1){http_response_code(400);echo 'Choose a valid personal data sheet.';exit;}
$db=(new Database())->getConnection();require_once __DIR__.'/../../../classes/OfficePolicy.php';$viewer=OfficePolicy::actor($db,(int)$user_info['id']);if(!in_array($viewer['role'],['admin','guidance_advocate','super_admin'],true)){http_response_code(403);exit;}
if($viewer['role']==='guidance_advocate'&&strtolower($_SERVER['HTTP_X_REQUESTED_WITH']??'')!=='xmlhttprequest'){http_response_code(403);echo 'Open this PDS from the portal. Printing requires counselor/admin approval.';exit;}
$stmt=$db->prepare('SELECT p.*,u.first_name AS account_first_name,u.middle_name AS account_middle_name,u.last_name AS account_last_name,u.email AS account_email,sp.student_id,sp.grade_level AS profile_grade,sp.program AS profile_program,sp.strand AS profile_strand FROM pds p JOIN users u ON p.user_id=u.id LEFT JOIN student_profiles sp ON p.user_id=sp.user_id WHERE p.id=? LIMIT 1');$stmt->execute([$id]);$data=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$data){http_response_code(404);echo 'Personal data sheet not found.';exit;}
foreach(['first_name'=>'account_first_name','middle_name'=>'account_middle_name','last_name'=>'account_last_name','email'=>'account_email','grade_level'=>'profile_grade','course'=>'profile_program','strand'=>'profile_strand'] as $field=>$fallback)if(trim((string)($data[$field]??''))==='')$data[$field]=$data[$fallback]??'';
$related=[];foreach(['pds_siblings','pds_organizations','pds_test_results'] as $table){try{$s=$db->prepare("SELECT * FROM $table WHERE user_id=? ORDER BY id");$s->execute([$data['user_id']]);$related[$table]=$s->fetchAll(PDO::FETCH_ASSOC);}catch(Exception $e){$related[$table]=[];}}
require_once __DIR__.'/../../../classes/StaffActivity.php';(new StaffActivity($db))->record((int)$viewer['id'],'admin_view_pds','view_student_pds');
$html=PDSPaperDocument::render($data,$related['pds_siblings'],$related['pds_organizations'],$related['pds_test_results']);
$isAjax=strtolower($_SERVER['HTTP_X_REQUESTED_WITH']??'')==='xmlhttprequest';if($isAjax){echo $html;exit;}
$base=PDSPaperDocument::baseUrl();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Personal Data Sheet</title><link rel="stylesheet" href="<?=PDSPaperDocument::e($base)?>assets/css/pds-paper.css?v=20261028-centered"><script src="<?=PDSPaperDocument::e($base)?>assets/js/pds-paper.js?v=20261028-2" defer></script></head><body><main class="pds-own-view" id="pdsStandalone"><div class="pds-own-actions"><a href="<?=PDSPaperDocument::e($base)?>dashboard/layout.php?page=admin_view_pds">Back to personal data sheets</a><button type="button" id="standalonePDSPrint">Print personal data sheet</button></div><?php readfile(__DIR__.'/../../../includes/pds_paper_toolbar.php');?><div class="pds-document-viewport"><?=$html?></div></main><script>document.addEventListener('DOMContentLoaded',async()=>{const scope=document.getElementById('pdsStandalone'),root=scope.querySelector('[data-pds-document]');try{await PDSPaper.mount(root,scope);}catch(error){}document.getElementById('standalonePDSPrint').addEventListener('click',()=>PDSPaper.print(root).catch(error=>{scope.querySelector('[data-pds-status]').textContent=error.message;}));});</script></body></html>
